lib = '''from collections import Counter

def background(grid):
    """The most common cell color in the grid."""
    return Counter(v for row in grid for v in row).most_common(1)[0][0]

def transpose(grid):
    """The grid reflected over its main diagonal."""
    return [list(col) for col in zip(*grid)]

def lines_of(grid, axis):
    """The grid's rows (axis='r') or columns (axis='c') as a list of lines."""
    return [list(r) for r in grid] if axis == 'r' else [[grid[i][j] for i in range(len(grid))] for j in range(len(grid[0]))]

def from_lines(lines, axis, height=None):
    """Rebuild a grid from its rows (axis='r') or columns (axis='c')."""
    if axis == 'r':
        return [list(l) for l in lines]
    h = height
    return [[l[i] for l in lines] for i in range(h)]

def find_tiling(lines, bg=None):
    """The smallest-period window of consecutive lines that reproduces every non-background line, tiled with its own phase: (axis-independent) (p, s, window) or None."""
    if bg is None:
        bg = Counter(v for l in lines for v in l).most_common(1)[0][0]
    n = len(lines)
    content = [i for i, l in enumerate(lines) if any(v != bg for v in l)]
    if not content:
        return None
    for p in range(1, n + 1):
        for s in range(0, n - p + 1):
            win = lines[s:s + p]
            if all(lines[i] == win[(i - s) % p] for i in content):
                return (p, s, win)
    return None

def tile_pattern(grid):
    """Tile the grid's repeating pattern block (rows or columns, whichever has the non-trivial period) over the whole grid, correcting blank or noisy lines."""
    H, W = len(grid), len(grid[0])
    for axis in ('r', 'c'):
        n = H if axis == 'r' else W
        res = find_tiling(lines_of(grid, axis))
        if res and res[0] < n:
            p, s, win = res
            tiled = [win[(i - s) % p] for i in range(n)]
            return from_lines(tiled, axis, height=H)
    return grid
